def beasts(heads, tails):
    "Orchestrates the solution by calling helper functions to determine the number of each beast."
    input_data = parse_input(heads, tails)
    result = solve_beast_equation(input_data)
    return format_output(result)

def parse_input(heads, tails):
    "Parses the input heads and tails into a dictionary for easier manipulation."
    return {'heads': heads, 'tails': tails}

def solve_beast_equation(input_data):
    "Solves the equation to find the number of each beast."
    heads = input_data['heads']
    tails = input_data['tails']

    # Define the equations for Orthus and Hydra
    # Orthus: 2 heads, 1 tail
    # Hydra: 5 heads, 1 tail

    # Let x be the number of Orthus and y be the number of Hydra
    # 2x + 5y = heads
    # x + y = tails

    # Solve the system of equations
    if tails < heads / 2 or tails > heads:
        return 'No solutions'

    # Using substitution or elimination method
    # x = tails - y
    # 2(tails - y) + 5y = heads
    # 2tails - 2y + 5y = heads
    # 2tails + 3y = heads
    # 3y = heads - 2tails
    # y = (heads - 2tails) / 3

    y = (heads - 2 * tails) / 3
    if y.is_integer() and y >= 0:
        x = tails - y
        return {'Orthus': int(x), 'Hydra': int(y)}
    else:
        return 'No solutions'

def format_output(result):
    "Formats the result into the required output format."
    if isinstance(result, dict):
        return [result['Orthus'], result['Hydra']]
    else:
        return result

def beasts(heads, tails):
    "Orchestrates the solution to determine the number of Orthus and Hydra creatures given the total number of heads and tails."
    return format_output(validate_input(heads, tails), solve_equations(heads, tails))

def validate_input(heads, tails):
    "Validates if the input heads and tails are non-negative integers."
    if heads < 0 or tails < 0:
        return None
    return heads, tails

def solve_equations(heads, tails):
    "Solves the system of equations to find the number of Orthus and Hydra creatures."
    x = (5 * heads - tails) / 3
    y = (2 * tails - heads) / 3
    if x.is_integer() and y.is_integer() and x >= 0 and y >= 0:
        return [int(x), int(y)]
    return None

def format_output(validated_input, solution):
    "Formats the output based on the solution validity."
    if solution is None:
        return 'No solutions'
    return solution

