def per(n):
    """Calculate the multiplicative persistence of a nonnegative integer n and return a list of intermediate products."""
    if n < 10:
        return []
    result = []
    while n >= 10:
        n = multiply_digits(n)
        result.append(n)
    return result

def multiply_digits(n):
    """Multiply all the digits of a nonnegative integer n and return the product."""
    product = 1
    while n > 0:
        product *= n % 10
        n //= 10
    return product

