def DPC_sequence(s):
    """Find the smallest DPC of a given string or return -1 if it doesn't exist."""
    def is_divisible(N, i):
        """Check if N is divisible by i."""
        return N % i == 0

    def is_relatively_prime(N, i):
        """Check if N and i are relatively prime."""
        return gcd(N, i) == 1

    def gcd(a, b):
        """Compute the greatest common divisor of a and b."""
        while b:
            a, b = b, a % b
        return a

    def find_DPC(s):
        """Find the smallest DPC of the string s."""
        N = 1
        for i, char in enumerate(s, start=1):
            if char == 'D':
                if not is_divisible(N, i):
                    return -1
            elif char == 'P':
                if not is_relatively_prime(N, i):
                    return -1
            elif char == 'C':
                if is_divisible(N, i) or is_relatively_prime(N, i):
                    return -1
            N += 1
        return N - 1

    return find_DPC(s)
