def custom_christmas_tree(chars, n):
    "Builds a custom Christmas tree with the specified characters and height."
    leaves = generate_leaves(chars, n)
    trunk = generate_trunk(n)
    return leaves + trunk

def generate_leaves(chars, n):
    "Generates the leaves part of the Christmas tree."
    leaves = []
    space_width = n - 1
    for i in range(n):
        row = ' ' * space_width
        for j in range(2 * i + 1):
            row += chars[j % len(chars)]
            if j < 2 * i:
                row += ' '
        leaves.append(row)
        space_width -= 1
    return '\n'.join(leaves) + '\n'

def generate_trunk(n):
    "Generates the trunk part of the Christmas tree."
    trunk_height = (n - 2) // 3 + 1
    trunk = [' ' * (n - 1) + '|'] * trunk_height
    return '\n'.join(trunk)

