def count_nice_swaps(data: dict) -> int:
    "Counts the number of ways to swap two elements to get a nice sequence."
    n = data['n']
    t = data['t']
    count = 0
    for i in range(n - 1):
        if i % 2 == 0 and t[i] >= t[i + 1]:
            for j in range(i + 1, n):
                if j % 2 == 1 and t[j] <= t[j - 1]:
                    if is_nice(t[:i] + [t[j]] + t[i:j] + [t[i]] + t[j + 1:]):
                        count += 1
        elif i % 2 == 1 and t[i] <= t[i + 1]:
            for j in range(i + 1, n):
                if j % 2 == 0 and t[j] >= t[j - 1]:
                    if is_nice(t[:i] + [t[j]] + t[i:j] + [t[i]] + t[j + 1:]):
                        count += 1
    return count

def is_nice(sequence: list) -> bool:
    "Checks if the given sequence is nice."
    n = len(sequence)
    for i in range(n - 1):
        if i % 2 == 0 and sequence[i] >= sequence[i + 1]:
            return False
        elif i % 2 == 1 and sequence[i] <= sequence[i + 1]:
            return False
    return True

