def solve():
    """Parse the input, unite the doubly linked lists, and print the result."""
    n = int(input())
    l = [0] * (n + 1)
    r = [0] * (n + 1)

    for i in range(1, n + 1):
        l[i], r[i] = map(int, input().split())

    head = find_head(n, l)
    tail = find_tail(n, r)
    new_r = list(range(1, n + 1))

    if head != 1:
        new_r[0] = head
        new_r[1] = l[head]
        l[head] = 1
    if tail != n:
        new_r[-1] = tail
        new_r[-2] = r[tail]
        r[tail] = n

    for i in range(2, n):
        new_r[i] = r[new_r[i - 1]]

    for i in range(1, n + 1):
        print(new_r[i - 1], new_r[i])

def find_head(n, l):
    """Find the head of the doubly linked list."""
    for i in range(1, n + 1):
        if l[i] == 0:
            return i
    return 1

def find_tail(n, r):
    """Find the tail of the doubly linked list."""
    for i in range(1, n + 1):
        if r[i] == 0:
            return i
    return n
