def process_sequence(start, sequence):
    "Processes the sequence starting from a given index and returns the final value of y or -1 if the program terminates."
    return run_program(start, sequence)

def run_program(x, sequence):
    "Runs the program with the given initial values of x and y, and the sequence. Returns the final value of y or -1 if the program terminates."
    n = len(sequence)
    y = 0
    while 1 <= x <= n:
        y += sequence[x - 1]
        x += sequence[x - 1]
        if x <= 0 or x > n:
            return -1
        y += sequence[x - 1]
        x -= sequence[x - 1]
    return y

