        for r in range(4):
            for c in range(n):
                if initial_state[r][c] == i:
                    targets[i] = (r, c)
                    break
            else:
                continue
            break

    # Find the initial positions of each car
    cars = {}
    for r in range(2, 4):
        for c in range(n):
            if initial_state[r][c] != 0:
                cars[initial_state[r][c]] = (r, c)

    # Function to check if a move is valid
    def is_valid_move(car, r, c):
        dr, dc = r - cars[car][0], c - cars[car][1]
        if abs(dr) + abs(dc) != 1:
            return False
        return True

    # Function to move a car
    def move_car(car, r, c):
        initial_state[cars[car][0]][cars[car][1]] = 0
        initial_state[r][c] = car
        cars[car] = (r, c)

    # Function to find a valid move for a car
    def find_valid_move(car):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = cars[car][0] + dr, cars[car][1] + dc
            if 0 <= r < 4 and 0 <= c < n and is_valid_move(car, r, c):
                return r, c
        return None

    # Function to solve the problem
    moves = []
    for car in range(1, k + 1):
