def solve():
    """Orchestrate the solution by reading input, processing it, and printing the result."""
    n, k = map(int, input().split())
    initial_state = [list(map(int, input().split())) for _ in range(4)]

    # Find the current positions and target positions of all cars
    current_positions = {}
    target_positions = {}
    for r in range(4):
        for c in range(n):
            car = initial_state[r][c]
            if car != 0:
                if r == 1 or r == 2:  # Current positions
                    current_positions[car] = (r, c)
                else:  # Target positions
                    target_positions[car] = (r, c)

    # Check if the initial state is already correct
    if current_positions == target_positions:
        print(0)
        return

    # Calculate the minimum number of moves required
    moves = 0
    for car in range(1, k + 1):
        if current_positions[car] != target_positions[car]:
            moves += abs(current_positions[car][0] - target_positions[car][0]) + abs(current_positions[car][1] - target_positions[car][1])

    # If the number of moves exceeds 20000, it's not possible
    if moves > 20000:
        print(-1)
        return

    # Output the moves
    for car in range(1, k + 1):
        if current_positions[car] != target_positions[car]:
            r1, c1 = current_positions[car]
            r2, c2 = target_positions[car]
            if r1 == r2:
                if c1 < c2:
                    for c in range(c1 + 1, c2 + 1):
                        print(f"{car} {r1} {c}")
