def solve():
    """Parse input, compute minimum and maximum scores, and print results."""
    n, m = map(int, input().split())
    variables = {}
    for _ in range(n):
        line = input().strip().split()
        name, _, expression = line[0], line[2], line[3:]
        variables[name] = expression

    min_score, max_score = compute_scores(variables, m)
    print(format(min_score, f'0{m}b'))
    print(format(max_score, f'0{m}b'))

def compute_scores(variables, m):
    """Compute minimum and maximum scores using dynamic programming."""
    from functools import lru_cache

    @lru_cache(None)
    def evaluate(expression, chosen):
        if isinstance(expression, str):
            if expression == '?':
                return chosen
            return variables[expression]
        op1, op2 = expression[0], expression[2]
        if expression[1] == 'AND':
            return evaluate(op1, chosen) & evaluate(op2, chosen)
        elif expression[1] == 'OR':
            return evaluate(op1, chosen) | evaluate(op2, chosen)
        elif expression[1] == 'XOR':
            return evaluate(op1, chosen) ^ evaluate(op2, chosen)

    min_score = float('inf')
    max_score = float('-inf')
    for chosen in range(2**m):
        score = sum(evaluate(variables[name], chosen) for name in variables)
        min_score = min(min_score, score)
        max_score = max(max_score, score)

    return min_score, max_score
