import sys

def solve():
    """Parse input, compute minimum and maximum scores, and print the results."""
    n, m = map(int, input().split())
    variables = {}

    for _ in range(n):
        line = input().strip().split()
        name = line[0]
        op = line[2]
        operand1 = line[3]
        operand2 = line[4] if len(line) > 4 else None

        if op == '?':
            variables[name] = ('?', m)
        else:
            variables[name] = (op, operand1, operand2)

    min_score, max_score = compute_scores(variables, m)
    print(f"{min_score:0{m}b}")
    print(f"{max_score:0{m}b}")

def compute_scores(variables, m):
    """Compute the minimum and maximum scores using dynamic programming."""
    from functools import lru_cache

    @lru_cache(None)
    def evaluate(var):
        if var[0] == '?':
            return 0, (1 << m) - 1
        op, op1, op2 = var
        val1, max1 = evaluate(variables[op1])
        if op2 is not None:
            val2, max2 = evaluate(variables[op2])
        else:
            val2, max2 = 0, (1 << m) - 1

        if op == 'AND':
            return val1 & val2, max1 & max2
        elif op == 'OR':
            return val1 | val2, max1 | max2
        elif op == 'XOR':
            return val1 ^ val2, max1 ^ max2

    min_score = float('inf')
    max_score = float('-inf')

    for i in range(1 << m):
        score = 0
        for name, var in variables.items():
            if var[0] == '?':
                score += i
        min_score = min(min_score, score)
        max_score = max(max_score, score)

    return min_score, max_score

# Entry point
if __name__ == "__main__":
    solve()
